function tone(frequency,offset,duration,volume=.07){if(!soundEnabled||audioContext?.state!=='running')return;const oscillator=audioContext.createOscillator(),gain=audioContext.createGain(),start=audioContext.currentTime+offset;oscillator.type='sine';oscillator.frequency.value=frequency;gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(volume,start+.015);gain.gain.exponentialRampToValueAtTime(.0001,start+duration);oscillator.connect(gain);gain.connect(audioContext.destination);tones.add(oscillator);oscillator.onended=()=>{tones.delete(oscillator);oscillator.disconnect();gain.disconnect();};oscillator.start(start);oscillator.stop(start+duration+.02);}
function messageSound(){if(window.__lchatNativeCall||(window.__lchatNativeInbox&&document.hidden))return;tone(880,0,.16);tone(1174,.12,.22);}
function ringBurst(){tone(640,0,.22);tone(880,.24,.22);tone(640,.50,.22);tone(880,.74,.28);}
function stopRinging(){clearInterval(ringTimer);ringTimer=null;ringToken='';for(const oscillator of tones){try{oscillator.stop();}catch{}}tones.clear();}
function syncRinging(){if(window.__lchatNativeInbox){stopRinging();return;}const token=incomingCall?.token||'';if(!token||!soundEnabled||!$('call-page').hidden){if(ringToken)stopRinging();return;}if(ringToken===token&&ringTimer)return;stopRinging();ringToken=token;ringBurst();ringTimer=setInterval(ringBurst,2300);}
