async function api(action,data={},post=false){
  const url=new URL(action==='me'||action.startsWith('room.')?'admin.php':'api.php',location.href);url.searchParams.set('action',action);
  const options={credentials:'same-origin',cache:'no-store'};
  if(post){options.method='POST';options.headers={'Content-Type':'application/json','X-CSRF-Token':csrf};options.body=JSON.stringify(data);}
  else Object.entries(data).forEach(([k,v])=>url.searchParams.set(k,String(v)));
  const controller=new AbortController();options.signal=controller.signal;const timeout=setTimeout(()=>controller.abort(),15000);
  try{const res=await fetch(url,options);let value;try{value=await res.json();}catch{throw new Error('Сервер вернул неверный ответ. Проверьте PHP и установку.');}
    if(!res.ok){const e=new Error(value.error||'Не удалось выполнить запрос.');e.status=res.status;throw e;}return value;
  }catch(e){if(e.name==='AbortError')throw new Error('Сервер долго не отвечает. Проверьте соединение.');throw e;}finally{clearTimeout(timeout);}
}
