function avatar(name,id=0,group=false){const n=node('span','avatar '+(group?'group':['violet','mint','peach','blue'][Number(id)%4]));if(group)n.append(icon('group'));else n.textContent=(name||'?').trim().slice(0,1).toUpperCase();return n;}
function timeText(raw){return raw?new Date(raw.replace(' ','T')+'Z').toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}):'';}
function dayText(raw){return new Date(raw.replace(' ','T')+'Z').toLocaleDateString('ru-RU',{day:'numeric',month:'long'});}
function linkFor(key,value){const u=new URL('index.php',publicBase||location.href);u.search='';u.hash='';if(key==='channel'){u.pathname=u.pathname.replace(/index\.php$/,'')+encodeURIComponent(value);}else u.searchParams.set(key,value);return u.href;}
