async function boot(){stopChatPolling();let d;try{d=await api('me');}catch(e){if([401,403].includes(e.status)){location.href='index.php';return;}throw e;}csrf=d.csrf;me=d.user;updateAccountState(d.call_state);publicBase=d.public_url||'';if(!me||!me.is_admin){location.href='index.php';return;}const token=new URLSearchParams(location.search).get('call');if(token){await openCall(token);return;}view('messenger');}function connection(ok){$('connection-dot').classList.toggle('offline',!ok);$('connection-label').textContent=ok?'Подключено':'Нет соединения · повторяем…';}
function applyChats(data){updateAccountState(data.call_state);let hasNew=false;for(const c of data.chats){const last=Number(c.last_incoming_id||0);if(snapshotReady&&last>(incomingSeen.get(Number(c.id))||0))hasNew=true;incomingSeen.set(Number(c.id),last);}snapshotReady=true;chats=data.chats;activeCalls=data.active_calls||[];connection(true);const signature=JSON.stringify(chats);if(signature!==sidebarSignature){sidebarSignature=signature;renderChats();}if(hasNew&&!incomingCall&&!rtc)messageSound();
  if(selected){const fresh=chats.find(c=>Number(c.id)===Number(selected.id));if(fresh){selected=fresh;updateHeading();}else closeChat();}
  showIncomingCalls(data.calls);
  updateCallBanner();
