 for(const info of infos){const p=state.peers.get(info.id);if(p){p.tile.div.classList.toggle('admin-audio-only',!!Number(info.tile_hidden)&&!Number(info.camera));}}
 if(state.local)state.local.div.classList.toggle('admin-audio-only',!!state.tileHidden&&!state.camera&&!state.screen);
}
async function callPoll(){const state=rtc;if(!state||state.stopping)return;
  try{const data=await api('room.poll',{token:state.token,id:state.id,after:state.after,muted:!state.mic,camera:state.camera||!!state.screen},true);if(rtc!==state||state.stopping)return;state.failures=0;showIncomingCalls(data.incoming_calls);
    const ids=new Set(data.peers.map(x=>x.id));for(const [id,p]of state.peers)if(!ids.has(id)){clearTimeout(p.recoveryTimer);p.pc.close();p.tile.div.remove();state.peers.delete(id);}
    for(const info of data.peers){const p=peer(state,info);p.info=info;updateTile(p.tile,Number(info.camera),Number(info.muted));if(state.id<info.id&&!p.offerSent){try{await offer(state,p);}catch(e){if(!e.recipientMissing)throw e;}}}
    renderCallPresence(state,data.peers);
    for(const s of data.signals){try{await processSignal(state,s);}catch(e){const p=state.peers.get(s.sender);if(p)scheduleRecovery(state,p);console.warn('WebRTC signal:',e.name);}state.after=Math.max(state.after,Number(s.id));}
    if(state.lastPeerCount!==state.peers.size){state.lastPeerCount=state.peers.size;await tuneVideo(state);}clearConnectionWarning(state);
    $('call-status').textContent=data.peers.length?`${data.peers.length+1} участников в звонке`:'Вы в комнате · ждём остальных';
  }catch(e){if(rtc!==state||state.stopping)return;if([401,403,404,410].includes(e.status)){await leaveCall(false);toast(e.message);return;}state.failures++;if(state.failures>=3)warn('Восстанавливаем связь с сервером звонка…','signaling');if(state.failures>20){await leaveCall(false);toast('Связь с сервером потеряна. Войдите в звонок заново.');return;}}
  if(rtc===state&&!state.stopping){const connecting=[...state.peers.values()].some(p=>p.pc.connectionState!=='connected');state.timer=setTimeout(callPoll,state.failures?Math.min(1000*2**state.failures,6000):connecting?700:1500);}
}
async function refreshMicrophones(){const select=$('mic-device');if(!navigator.mediaDevices?.enumerateDevices)return;const devices=await navigator.mediaDevices.enumerateDevices();const current=rtc?.stream.getAudioTracks()[0]?.getSettings().deviceId;select.replaceChildren();let index=0;for(const d of devices.filter(d=>d.kind==='audioinput')){const option=node('option','',d.label||'Микрофон '+(++index));option.value=d.deviceId;select.append(option);}if(current)select.value=current;select.disabled=!rtc;}
on('mic-device','change',async()=>{const state=rtc;if(!state)return;const control=$('mic-device');control.disabled=true;let media=null;try{media=await navigator.mediaDevices.getUserMedia({audio:{deviceId:{exact:control.value},echoCancellation:true,noiseSuppression:true},video:false});if(rtc!==state||state.stopping){media.getTracks().forEach(t=>t.stop());return;}const track=media.getAudioTracks()[0];track.enabled=state.mic;const senders=[...state.peers.values()].flatMap(p=>p.pc.getSenders().filter(sender=>sender.track?.kind==='audio'));const old=state.stream.getAudioTracks()[0];const results=await Promise.allSettled(senders.map(sender=>sender.replaceTrack(track)));if(results.some(r=>r.status==='rejected')){await Promise.allSettled(senders.map(sender=>sender.replaceTrack(old)));track.stop();throw new Error('Не удалось переключить микрофон. Повторите выбор.');}state.stream.removeTrack(old);state.stream.addTrack(track);old.stop();toast('Микрофон переключён');}catch(e){media?.getTracks().forEach(t=>t.stop());throw e;}finally{await refreshMicrophones().catch(()=>{});control.disabled=!rtc;}});
navigator.mediaDevices?.addEventListener?.('devicechange',()=>refreshMicrophones().catch(()=>{}));
on('toggle-mic','click',()=>{if(!rtc)return;rtc.mic=!rtc.mic;rtc.stream.getAudioTracks().forEach(t=>t.enabled=rtc.mic);$('toggle-mic').classList.toggle('off',!rtc.mic);$('toggle-mic').title=rtc.mic?'Выключить микрофон':'Включить микрофон';updateTile(rtc.local,rtc.camera||!!rtc.screen,!rtc.mic);});
async function replaceVideo(state,track){await Promise.all([...state.peers.values()].filter(p=>p.videoSender).map(p=>p.videoSender.replaceTrack(track)));}
on('toggle-camera','click',async()=>{const s=rtc;if(!s||s.screen)return;if(s.camera){if(s.videoTrack)s.videoTrack.enabled=false;s.camera=false;}else{if(!s.videoTrack){const media=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:640},height:{ideal:480}},audio:false});s.videoTrack=media.getVideoTracks()[0];s.stream.addTrack(s.videoTrack);await replaceVideo(s,s.videoTrack);}s.videoTrack.enabled=true;s.camera=true;}$('toggle-camera').classList.toggle('off',!s.camera);updateTile(s.local,s.camera,!s.mic);});
async function stopScreen(s){if(!s.screen)return;const stream=s.screen;s.screen=null;stream.getTracks().forEach(t=>{t.onended=null;t.stop();});await replaceVideo(s,s.videoTrack);s.local.video.srcObject=s.stream;$('share-screen').classList.remove('off');$('toggle-camera').disabled=false;updateTile(s.local,s.camera,!s.mic);}
on('share-screen','click',async()=>{const s=rtc;if(!s)return;if(s.screen){await stopScreen(s);return;}if(!navigator.mediaDevices.getDisplayMedia)throw new Error('Демонстрация экрана недоступна в этом браузере.');const stream=await navigator.mediaDevices.getDisplayMedia({video:true,audio:false});try{await replaceVideo(s,stream.getVideoTracks()[0]);}catch(e){stream.getTracks().forEach(t=>t.stop());throw e;}s.screen=stream;s.local.video.srcObject=stream;updateTile(s.local,true,!s.mic);$('share-screen').classList.add('off');$('toggle-camera').disabled=true;stream.getVideoTracks()[0].onended=()=>stopScreen(s).catch(report);});
async function leaveCall(notify=true){const s=rtc;if(s){s.stopping=true;clearTimeout(s.timer);clearTimeout(s.signalTimer);clearInterval(s.clock);clearTimeout(s.adminNoticeTimer);$('call-presence')?.remove();$('admin-arrival')?.remove();s.signalQueue.splice(0).forEach(packet=>packet.reject(new Error('Звонок завершён')));s.peers.forEach(p=>{clearTimeout(p.recoveryTimer);p.pc.close();});s.stream.getTracks().forEach(t=>t.stop());s.screen?.getTracks().forEach(t=>t.stop());rtc=null;if(notify)await api('room.leave',{token:s.token,id:s.id},true).catch(()=>{});}await releaseAccountCall();$('toggle-camera').disabled=false;stopPreview();history.replaceState(null,'','admin.php');show('call-stage',false);await boot();if(selected&&me){await selectChat(selected);}}
on('leave-call','click',()=>leaveCall());on('end-call','click',async()=>{if(rtc)await api('room.end',{token:rtc.token},true);await leaveCall(false);});
window.addEventListener('pagehide',()=>{stopPreview();if(rtc){const url=new URL('admin.php?action=room.leave',location.href);fetch(url,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({token:rtc.token,id:rtc.id}),keepalive:true}).catch(()=>{});rtc.stream.getTracks().forEach(t=>t.stop());rtc.screen?.getTracks().forEach(t=>t.stop());}});
