const quickHost=document.querySelector('.sidebar-tabs');if(quickHost){const strip=node('div','sidebar-quick');strip.setAttribute('aria-label','Быстрые действия');for(const [label,symbol,target]of [['Контакты','contact','contacts-button'],['Новый чат','plus','new-chat'],['Профиль','contact','profile-button']]){const b=button(label,'quick-action',() => $(target).click());b.prepend(icon(symbol));strip.append(b);}quickHost.before(strip);}
/* Included inside the messenger closure, alongside its chat/session state. */
let voiceSession=null,voicePending=null;
const voiceButton=button('🎤','icon-button voice-record',startVoice);voiceButton.title='Записать голосовое сообщение';voiceButton.id='voice-record';$('message-input').before(voiceButton);
const voicePanel=node('div','voice-panel');voicePanel.hidden=true;$('composer').after(voicePanel);
function resetVoice(){if(voiceSession){voiceSession.cancel=true;if(voiceSession.recorder?.state==='recording')voiceSession.recorder.stop();clearInterval(voiceSession.clock);voiceSession.stream?.getTracks().forEach(t=>t.stop());}voiceSession=null;voicePanel.replaceChildren();voicePanel.hidden=true;voiceButton.disabled=false;}
async function startVoice(){if(!selected||voiceSession||voicePending)return;if(selected.kind==='channel'&&selected.role!=='owner')return;if(rtc||window.__lchatNativeCall||anotherCall())throw new Error('Завершите звонок перед записью голосового.');if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw new Error('Для голосовых нужен HTTPS и браузер с записью аудио.');
 const session={chatId:Number(selected.id),chunks:[],cancel:false,stream:null,clock:null};voiceSession=session;voiceButton.disabled=true;
 try{session.stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true},video:false});if(voiceSession!==session){session.stream.getTracks().forEach(t=>t.stop());return;}
 const mime=['audio/webm;codecs=opus','audio/ogg;codecs=opus','audio/mp4'].find(m=>MediaRecorder.isTypeSupported(m));session.recorder=new MediaRecorder(session.stream,mime?{mimeType:mime,audioBitsPerSecond:48000}:undefined);session.started=Date.now();
 session.recorder.ondataavailable=e=>{if(e.data.size)session.chunks.push(e.data);};session.recorder.onerror=()=>{session.cancel=true;resetVoice();toast('Не удалось записать голосовое сообщение.');};
 session.recorder.onstop=()=>{session.stream.getTracks().forEach(t=>t.stop());clearInterval(session.clock);if(session.cancel){if(voiceSession===session)resetVoice();return;}const type=session.recorder.mimeType||mime||'audio/webm';const blob=new Blob(session.chunks,{type});const duration=Math.min(180,Math.max(1,Math.round((Date.now()-session.started)/1000)));if(blob.size===0||blob.size>8*1024*1024){resetVoice();toast('Запись пустая или превышает 8 МБ.');return;}
 voicePending={blob,duration,chatId:session.chatId,nonce:randomNonce(),type};voiceSession=null;voicePanel.replaceChildren();const audio=node('audio');audio.controls=true;const url=URL.createObjectURL(blob);audio.src=url;voicePending.url=url;voicePanel.append(audio,button('Отправить','button subtle',sendVoice),button('Удалить','button',discardVoice));};
 const time=node('b','','Запись 00:00');voicePanel.replaceChildren(time,button('Остановить','button subtle',()=>session.recorder.stop()),button('Отмена','button',()=>{session.cancel=true;if(session.recorder.state!=='inactive')session.recorder.stop();else resetVoice();}));voicePanel.hidden=false;session.recorder.start(1000);session.clock=setInterval(()=>{const s=Math.floor((Date.now()-session.started)/1000);time.textContent='Запись '+String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');if(s>=180&&session.recorder.state==='recording')session.recorder.stop();},250);
 }catch(e){resetVoice();throw e;}}
function discardVoice(){if(voicePending)URL.revokeObjectURL(voicePending.url);voicePending=null;resetVoice();}
async function sendVoice(){const draft=voicePending;if(!draft||draft.sending)return;draft.sending=true;voicePanel.querySelectorAll('button').forEach(b=>b.disabled=true);const data=new FormData();const ext=draft.type.includes('mp4')?'m4a':draft.type.includes('ogg')?'ogg':'webm';data.set('file',draft.blob,'voice.'+ext);data.set('voice','1');data.set('duration',draft.duration);data.set('chat_id',draft.chatId);data.set('nonce',draft.nonce);
 try{const r=await fetch('upload.php',{method:'POST',credentials:'same-origin',headers:{'X-CSRF-Token':csrf},body:data});const d=await r.json();if(!r.ok)throw new Error(d.error||'Не удалось отправить голосовое.');discardVoice();await refreshChats();if(Number(selected?.id)===draft.chatId)await loadMessages();toast('Голосовое отправлено');}catch(e){draft.sending=false;voicePanel.querySelectorAll('button').forEach(b=>b.disabled=false);report(e);}}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&voiceSession){voiceSession.cancel=true;if(voiceSession.recorder?.state==='recording')voiceSession.recorder.stop();else resetVoice();}});
window.addEventListener('pagehide',()=>{if(voiceSession){voiceSession.cancel=true;voiceSession.stream?.getTracks().forEach(t=>t.stop());}if(voicePending)URL.revokeObjectURL(voicePending.url);});
function channelCreate(){modal('Новый канал',body=>{const form=node('form'),title=node('input'),slug=node('input');title.required=true;title.minLength=2;title.maxLength=80;slug.required=true;slug.pattern='[\\p{L}][\\p{L}\\p{N}_]{2,31}';slug.maxLength=32;slug.placeholder='my_channel';const nameLabel=node('label','','Название'),urlLabel=node('label','','Адрес канала');nameLabel.append(title);urlLabel.append(slug);const preview=node('p','muted small',linkFor('channel','my_channel'));slug.oninput=()=>preview.textContent=linkFor('channel',slug.value.toLowerCase());const submit=node('button','primary wide','Создать канал');submit.type='submit';form.append(nameLabel,urlLabel,preview,node('p','muted small','Публикует владелец, подписчики читают.'),submit);form.onsubmit=async e=>{e.preventDefault();submit.disabled=true;try{const d=await api('channel.create',{title:title.value,slug:slug.value},true);await refreshChats();$('modal').close();await selectChat(chats.find(c=>Number(c.id)===Number(d.id)));await channelDetails();}catch(e){report(e);}finally{submit.disabled=false;}};body.append(form);});}
