async function channelDetails(){const c=selected;if(!c)return;modal(c.title,body=>{body.append(node('p','muted',c.member_count+' подписчиков'),button('Скопировать ссылку','button subtle wide',()=>copy(linkFor('channel',c.channel_slug))));if(c.role==='owner'){const slug=node('input');slug.value=c.channel_slug;const label=node('label','','Изменить адрес');label.append(slug);body.append(label,button('Сохранить адрес','primary wide',async()=>{await api('channel.update',{chat_id:c.id,slug:slug.value},true);await refreshChats();await channelDetails();}));}else body.append(button('Отписаться','button wide',async()=>{await api('channel.leave',{chat_id:c.id},true);$('modal').close();closeChat();await refreshChats();}));});}

