let messageMenu=null,menuTrigger=null,pressTimer=null,pressPoint=null,longPressed=false,deletionOffset=0;
function closeMessageMenu(){if(messageMenu){messageMenu.remove();messageMenu=null;}if(menuTrigger?.isConnected)menuTrigger.classList.remove('context-selected');menuTrigger=null;}
function canDeleteMessage(m){return Number(m.user_id)===Number(me?.id)||!!me?.is_admin||(['group','channel'].includes(selected?.kind)&&selected?.role==='owner');}
function openMessageMenu(row,x,y){const m=messages.find(m=>Number(m.id)===Number(row.dataset.messageId));if(!m||!selected)return;closeMessageMenu();menuTrigger=row;row.classList.add('context-selected');const menu=node('div','message-context-menu');messageMenu=menu;menu.setAttribute('role','menu');menu.setAttribute('aria-label','Действия с сообщением');
 const copyAction=button('Копировать текст','message-menu-item',()=>{closeMessageMenu();return copy(m.body);});copyAction.setAttribute('role','menuitem');menu.append(copyAction);
 if(canDeleteMessage(m)){const remove=button('Удалить','message-menu-item destructive',()=>{closeMessageMenu();confirmMessageDelete(m,Number(selected.id));});remove.setAttribute('role','menuitem');menu.append(remove);}document.body.append(menu);const r=menu.getBoundingClientRect();menu.style.left=Math.max(8,Math.min(x,innerWidth-r.width-8))+'px';menu.style.top=Math.max(8,Math.min(y,innerHeight-r.height-8))+'px';menu.querySelector('button').focus();
 menu.addEventListener('keydown',e=>{const items=[...menu.querySelectorAll('button')],i=items.indexOf(document.activeElement);if(e.key==='Escape'){e.preventDefault();closeMessageMenu();row.focus();}else if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();items[(i+(e.key==='ArrowDown'?1:items.length-1))%items.length].focus();}});
}
function confirmMessageDelete(m,chatId){modal('Удалить сообщение?',body=>{body.append(node('p','muted','Сообщение и вложение будут удалены у всех участников. Отменить удаление нельзя.'),button('Удалить у всех','button message-delete-confirm',async()=>{const control=$('modal-body').querySelector('.message-delete-confirm');control.disabled=true;try{await api('message.delete',{chat_id:chatId,message_id:Number(m.id)},true);$('modal').close();if(Number(selected?.id)===chatId){const box=$('messages'),top=box.scrollTop;removeVisibleMessages([Number(m.id)]);box.scrollTop=top;}await refreshChats();toast('Сообщение удалено');}catch(e){control.disabled=false;report(e);}}),button('Отмена','button subtle',()=> $('modal').close()));});}
function removeVisibleMessages(ids){const set=new Set(ids.map(Number));let changed=false;for(const row of $('message-items').querySelectorAll('[data-message-id]'))if(set.has(Number(row.dataset.messageId))){row.querySelectorAll('audio').forEach(a=>{a.pause();a.removeAttribute('src');a.load();});row.remove();changed=true;}messages=messages.filter(m=>!set.has(Number(m.id)));if(changed){closeMessageMenu();for(const date of [...$('message-items').querySelectorAll('.message-date')])if(!date.nextElementSibling||date.nextElementSibling.classList.contains('message-date'))date.remove();if(!messages.length)$('message-items').append(node('p','list-empty','Сообщений пока нет.'));}}
const messageList=$('message-items');messageList.addEventListener('contextmenu',e=>{const row=e.target.closest('.message[data-message-id]');if(!row)return;e.preventDefault();openMessageMenu(row,e.clientX,e.clientY);});
messageList.addEventListener('keydown',e=>{if(e.key==='ContextMenu'||(e.shiftKey&&e.key==='F10')){const row=e.target.closest('.message');if(!row)return;e.preventDefault();const r=row.getBoundingClientRect();openMessageMenu(row,r.left+30,r.top+20);}});
messageList.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'||e.target.closest('audio,button,a,input'))return;const row=e.target.closest('.message');if(!row)return;clearTimeout(pressTimer);longPressed=false;pressPoint={x:e.clientX,y:e.clientY};pressTimer=setTimeout(()=>{longPressed=true;openMessageMenu(row,e.clientX,e.clientY);},550);});
messageList.addEventListener('pointermove',e=>{if(pressPoint&&(Math.abs(e.clientX-pressPoint.x)>10||Math.abs(e.clientY-pressPoint.y)>10))clearTimeout(pressTimer);});
for(const name of ['pointerup','pointercancel'])messageList.addEventListener(name,()=>{clearTimeout(pressTimer);pressPoint=null;});
messageList.addEventListener('click',e=>{if(longPressed){e.preventDefault();e.stopImmediatePropagation();longPressed=false;}},true);
document.addEventListener('pointerdown',e=>{if(messageMenu&&!messageMenu.contains(e.target)&&!e.target.closest('.context-selected'))closeMessageMenu();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMessageMenu();});$('messages').addEventListener('scroll',closeMessageMenu,{passive:true});window.addEventListener('resize',closeMessageMenu);window.addEventListener('pagehide',closeMessageMenu);

boot().catch(e=>{view(me?'messenger':'auth');show('auth-error',false);report(e);});
