</script><script>(() => {
const $=id=>document.getElementById(id),el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};let csrf='',after=0,search='',busy=false,refreshing=false;
function status(t,error=false){$('admin-status').textContent=t;$('admin-status').style.color=error?'#bb354a':'';}
async function api(action,data={},post=false){const url=new URL('admin.php',location.href);url.searchParams.set('action',action);const opts={credentials:'same-origin',cache:'no-store'};if(post){opts.method='POST';opts.headers={'Content-Type':'application/json','X-CSRF-Token':csrf};opts.body=JSON.stringify(data);}else for(const[k,v]of Object.entries(data))url.searchParams.set(k,v);const res=await fetch(url,opts),body=await res.json();if(!res.ok)throw new Error(body.error||'Ошибка запроса');return body;}
function button(label,fn){const b=el('button',label);b.type='button';b.onclick=async()=>{b.disabled=true;try{await fn();}catch(e){status(e.message,true);}finally{b.disabled=false;}};return b;}
async function overview(){const d=await api('overview');$('admin-stats').replaceChildren(...[['users','Пользователей'],['chats','Чатов'],['messages','Сообщений']].map(([k,label])=>{const n=el('div',undefined,'admin-stat');n.append(el('strong',d.stats[k]),el('span',label));return n;}));$('admin-rooms').replaceChildren();for(const r of d.rooms){const row=el('div',undefined,'admin-row'),info=el('div'),actions=el('div',undefined,'admin-actions');info.append(el('b',r.title),el('small',`@${r.owner} · ${r.participants} участников · ${Number(r.is_public)?'по ссылке':'закрытый чат'}`));actions.append(button('Присоединиться',()=>document.dispatchEvent(new CustomEvent('admin-join',{detail:r.token}))),button('Завершить',async()=>{if(!confirm('Завершить звонок для всех?'))return;await api('room.end',{token:r.token},true);await overview();}));row.append(info,actions);$('admin-rooms').append(row);}if(!d.rooms.length)$('admin-rooms').append(el('p','Сейчас нет активных звонков.'));}
async function users(reset=true){if(busy)return;busy=true;$('admin-more').disabled=true;try{if(reset){after=0;search=$('admin-query').value.trim();}const d=await api('users',{q:search,after});if(reset)$('admin-users').replaceChildren();for(const u of d.users){const n=el('div',undefined,'admin-row'),info=el('div');info.append(el('b',`${u.name} · @${u.username}`),el('small',u.email),el('small',`Регистрация: ${u.created_at} UTC`));n.dataset.admin=(d.admin_ids||[]).includes(Number(u.id))?'1':'0';n.dataset.userId=u.id;n.dataset.username=u.username;n.dataset.blocked=u.ban_reason?'1':'0';n.append(info);if(u.ban_reason)n.append(el('small','Заблокирован: '+u.ban_reason));$('admin-users').append(n);}after=d.next;$('admin-more').hidden=!d.has_more;if(reset&&!d.users.length)$('admin-users').append(el('p','Пользователи не найдены.'));}finally{busy=false;$('admin-more').disabled=false;}}
async function refresh(){if(refreshing)return;refreshing=true;try{await Promise.all([overview(),users()]);status('Данные загружены.');}catch(e){status(e.message,true);}finally{refreshing=false;}}
$('admin-refresh').onclick=refresh;$('admin-more').onclick=()=>users(false).catch(e=>status(e.message,true));$('admin-search').onsubmit=e=>{e.preventDefault();users().catch(e=>status(e.message,true));};
setInterval(()=>{if(!document.hidden&&!refreshing&&!$('admin-dashboard').hidden){refreshing=true;overview().catch(e=>status(e.message,true)).finally(()=>refreshing=false);}},10000);
(async()=>{try{const r=await fetch('admin.php?action=me',{credentials:'same-origin',cache:'no-store'});const me=await r.json();csrf=me.csrf;await refresh();}catch(e){status(e.message,true);}})();
})();</script><script>(()=>{
const $=id=>document.getElementById(id),el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};let csrf='',myId=0,chatAfter=0,activeChat=0,oldest=0,pending=null;
function status(text,error=false){$('admin-status').textContent=text;$('admin-status').style.color=error?'#bb354a':'';}
async function api(action,data={},post=false){const url=new URL('admin.php',location.href);url.searchParams.set('action',action);const opts={credentials:'same-origin',cache:'no-store'};if(post){opts.method='POST';opts.headers={'Content-Type':'application/json','X-CSRF-Token':csrf};opts.body=JSON.stringify(data);}else for(const[k,v]of Object.entries(data))url.searchParams.set(k,v);const res=await fetch(url,opts),body=await res.json();if(!res.ok)throw new Error(body.error||'Ошибка запроса');return body;}
function action(label,fn){const b=el('button',label);b.type='button';b.onclick=async()=>{b.disabled=true;try{await fn();}catch(e){status(e.message,true);}finally{b.disabled=false;}};return b;}
function decorate(){if(!myId)return;for(const row of $('admin-users').querySelectorAll('[data-user-id]')){if(row.dataset.actions||row.dataset.admin==='1'||Number(row.dataset.userId)===myId)continue;row.dataset.actions='1';const blocked=row.dataset.blocked==='1';row.append(action(blocked?'Разблокировать':'Заблокировать',async()=>{const reason=blocked?'Разблокировка':prompt('Причина блокировки аккаунта:','Нарушение правил');if(reason===null||!reason.trim())return;await api('ban',{user_id:Number(row.dataset.userId),blocked:!blocked,reason:reason.trim()},true);row.dataset.blocked=blocked?'0':'1';delete row.dataset.actions;row.lastChild.remove();decorate();status('Статус аккаунта обновлён.');}));}}
new MutationObserver(decorate).observe($('admin-users'),{childList:true,subtree:true});
async function chats(reset=true){const d=await api('chats',{q:$('mod-chat-query').value.trim(),after:reset?0:chatAfter});if(reset)$('mod-chats').replaceChildren();for(const c of d.chats){const row=el('div',undefined,'admin-row'),info=el('div');info.append(el('b',c.title||('Личный чат #'+c.id)),el('small',c.people||'Нет участников'));row.append(info,action('Открыть',()=>messages(Number(c.id))));$('mod-chats').append(row);}chatAfter=d.next;$('mod-chats-more').hidden=!d.has_more;if(reset&&!d.chats.length)$('mod-chats').append(el('p','Чаты не найдены.'));}
function message(m){const row=el('div',undefined,'mod-message'+(m.moderator?' mod-notice':''));row.append(el('b',`${m.name} · @${m.username}${m.moderator?' · администратор':''}`),el('small',m.created_at+' UTC'),el('p',m.body));if(m.file_name){const a=el('a',m.file_name);a.href='admin.php?action=file&id='+encodeURIComponent(m.id);a.download='';row.append(a);}const remove=action('Удалить сообщение',async()=>{if(!confirm('Удалить это сообщение и его вложение для всех участников?'))return;const id=activeChat;await api('chat.delete',{chat_id:id,message_id:Number(m.id)},true);if(id===activeChat)await messages(id);await audit();status('Сообщение удалено.');});remove.classList.add('mod-delete');row.append(remove);return row;}
async function messages(id,older=false){const d=await api('chat.messages',{chat_id:id,before:older?oldest:0});if(!older){activeChat=id;$('mod-messages').replaceChildren();$('mod-conversation').hidden=false;$('mod-title').textContent=d.chat.title||'Личный чат #'+id;}if(id!==activeChat)return;const nodes=d.messages.map(message);if(older)$('mod-messages').prepend(...nodes);else $('mod-messages').append(...nodes);if(d.messages.length)oldest=Number(d.messages[0].id);$('mod-older').hidden=!d.has_more;if(!older&&!d.messages.length)$('mod-messages').append(el('p','Пока нет сообщений.'));}
$('mod-chat-search').onsubmit=e=>{e.preventDefault();chats().catch(e=>status(e.message,true));};$('mod-chats-more').onclick=()=>chats(false).catch(e=>status(e.message,true));$('mod-older').onclick=()=>messages(activeChat,true).catch(e=>status(e.message,true));
$('mod-send').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button'),body=$('mod-text').value.trim();if(!activeChat||!body)return;b.disabled=true;const id=activeChat;if(!pending||pending.id!==id||pending.body!==body){const bytes=new Uint8Array(16);crypto.getRandomValues(bytes);pending={id,body,nonce:Array.from(bytes,x=>x.toString(16).padStart(2,'0')).join('')};}try{await api('chat.send',{chat_id:id,body,nonce:pending.nonce},true);pending=null;$('mod-text').value='';if(id===activeChat)await messages(id);status('Сообщение администратора отправлено.');}catch(e){status(e.message,true);}finally{b.disabled=false;}};
async function audit(){const d=await api('audit');$('mod-audit').replaceChildren(...d.events.map(e=>{const row=el('div',undefined,'admin-row');row.append(el('span',`${e.created_at} UTC · @${e.username||e.actor_id} · ${e.action} · ${e.target}`));return row;}));if(!d.events.length)$('mod-audit').append(el('p','Действий пока нет.'));}$('mod-audit-load').onclick=()=>audit().catch(e=>status(e.message,true));
(async()=>{try{const res=await fetch('admin.php?action=me',{credentials:'same-origin',cache:'no-store'}),me=await res.json();csrf=me.csrf;myId=Number(me.user.id);decorate();await chats();await audit();}catch(e){status(e.message,true);}})();
})();
</script><script>
(()=>{
const $=id=>document.getElementById(id);let csrf='';
function notice(t,error=false){$('admin-status').textContent=t;$('admin-status').style.color=error?'#bb354a':'';}
async function api(action,data){const url=new URL('admin.php',location.href);url.searchParams.set('action',action);const opts={credentials:'same-origin',cache:'no-store'};if(data){opts.method='POST';opts.headers={'Content-Type':'application/json','X-CSRF-Token':csrf};opts.body=JSON.stringify(data);}const response=await fetch(url,opts),body=await response.json();if(!response.ok)throw new Error(body.error||'Ошибка запроса');return body;}
async function list(){const d=await api('admins');$('mod-add-admin').hidden=!d.can_manage;$('mod-admin-list').replaceChildren();for(const user of d.admins){const row=document.createElement('div');row.className='admin-row';const label=document.createElement('span');label.textContent=user.name+' · @'+user.username+(Number(user.id)===Number(d.owner_id)?' · владелец':' · администратор');row.append(label);if(d.can_manage&&Number(user.id)!==Number(d.owner_id)){const b=document.createElement('button');b.type='button';b.textContent='Убрать права';b.onclick=async()=>{if(!confirm('Убрать права у @'+user.username+'?'))return;b.disabled=true;try{await api('admin.remove',{user_id:Number(user.id)});await list();$('admin-refresh').click();notice('Права администратора отозваны.');}catch(e){notice(e.message,true);b.disabled=false;}};row.append(b);}$('mod-admin-list').append(row);}}
$('mod-add-admin').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api('admin.add',{username:$('mod-admin-username').value.trim()});$('mod-admin-username').value='';await list();$('admin-refresh').click();notice('Администратор добавлен. Ваши права сохранены.');}catch(e){notice(e.message,true);}finally{b.disabled=false;}};
(async()=>{try{const me=await api('me');csrf=me.csrf;await list();}catch(e){notice(e.message,true);}})();
})();
</script><script>(()=>{
const root=document.getElementById('admin-dashboard');if(!root)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const sections=[...root.querySelectorAll(':scope > section')],links=[...root.querySelectorAll('.admin-nav a')];
if(!reduced&&'IntersectionObserver'in window){const reveal=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('visible');reveal.unobserve(e.target);}},{threshold:.08});sections.forEach((s,i)=>{s.classList.add('admin-reveal');s.style.transitionDelay=Math.min(i*45,180)+'ms';reveal.observe(s);});}
if('IntersectionObserver'in window){const nav=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting)links.forEach(a=>{const active=a.hash==='#'+e.target.id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});},{rootMargin:'-15% 0px -55% 0px',threshold:0});sections.forEach(s=>nav.observe(s));}
if(!reduced)root.addEventListener('pointerdown',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const r=b.getBoundingClientRect(),size=Math.max(r.width,r.height),wave=document.createElement('span');wave.className='admin-ripple';Object.assign(wave.style,{width:size+'px',height:size+'px',left:(e.clientX-r.left-size/2)+'px',top:(e.clientY-r.top-size/2)+'px'});b.append(wave);setTimeout(()=>wave.remove(),600);});
const values=new Map(),stats=document.getElementById('admin-stats');if(stats&&!reduced){new MutationObserver(entries=>{for(const entry of entries)for(const node of entry.addedNodes){if(node.nodeType!==1||!node.classList.contains('admin-stat'))continue;const strong=node.querySelector('strong'),label=node.querySelector('span')?.textContent,target=Number(strong?.textContent);if(!strong||!Number.isFinite(target))continue;const from=values.get(label)??0;values.set(label,target);if(from===target)continue;const start=performance.now();function frame(now){if(!strong.isConnected)return;const t=Math.min(1,(now-start)/550);strong.textContent=String(Math.round(from+(target-from)*(1-Math.pow(1-t,3))));if(t<1)requestAnimationFrame(frame);}requestAnimationFrame(frame);}}).observe(stats,{childList:true});}
})();
</script><style>.site-settings-form{display:grid;gap:14px}.site-settings-form label{display:grid;gap:6px;font-size:13px}.site-settings-form input:not([type=checkbox]),.site-settings-form select{width:100%;padding:11px;border:1px solid #8ca4c052;border-radius:9px;background:#172232;color:#edf4ff}.site-settings-form .site-check{display:flex;align-items:center;gap:10px}.site-actions{display:flex;gap:8px;flex-wrap:wrap}#site-settings-note{font-size:12px;color:#9baec7}</style><script>(()=>{
const form=document.getElementById('site-settings-form'),section=document.getElementById('admin-settings-section'),note=document.getElementById('site-settings-note');let csrf='';
async function request(action,data){const options={credentials:'same-origin',cache:'no-store'};if(data){options.method='POST';options.headers={'Content-Type':'application/json','X-CSRF-Token':csrf};options.body=JSON.stringify(data);}const r=await fetch('admin.php?action='+encodeURIComponent(action),options),d=await r.json();if(!r.ok){const e=new Error(d.error||'Request failed');e.status=r.status;throw e;}return d;}
async function load(){const s=await request('site.settings');section.hidden=false;for(const key of ['site_name','max_call_participants','call_transport','turn_urls','turn_ttl'])form.elements[key].value=s[key];form.elements.registration_open.checked=s.registration_open;form.elements.turn_secret.value='';note.textContent=(s.turn_secret_set?'Секрет TURN задан.':'Секрет TURN не задан.')+(s.turn_multiple?' При сохранении будет использован только показанный адрес TURN.':'');}
form.addEventListener('submit',async e=>{e.preventDefault();const b=form.querySelector('[type=submit]');b.disabled=true;try{const data=Object.fromEntries(new FormData(form));data.registration_open=form.elements.registration_open.checked;await request('site.save',data);await load();note.textContent='Настройки сохранены. Обновите мессенджер.';}catch(err){note.textContent=err.message;}finally{b.disabled=false;}});
document.getElementById('site-settings-reset').addEventListener('click',async()=>{if(!confirm('Сбросить настройки к значениям из config.php?'))return;try{await request('site.reset',{});await load();note.textContent='Настройки сброшены.';}catch(err){note.textContent=err.message;}});
(async()=>{try{const me=await request('me');csrf=me.csrf;await load();}catch(e){if(e.status!==403){section.hidden=false;note.textContent=e.message;}}})();
})();</script></body></html>
